<?php foreach($posts as $post): ?><article id="berita-<?= e($post['slug']) ?>" class="<?= $post['category']==='behind_scenes'?'card':'berita card card-border-merah' ?>"><div class="berita-gambar"><img src="<?= e($post['cover_url']??'images/hero-news.jpg') ?>" alt="<?= e($post['title']) ?>"></div><span class="pill"><?= e($post['tag']??ucfirst($post['category'])) ?></span><p class="berita-tanggal"><?= e(tanggal_id($post['published_at'])) ?></p><h3 class="berita-judul"><?= e($post['title']) ?></h3><p class="paragraf-kecil"><?= e($post['excerpt']??'') ?></p><a class="link-merah" href="berita-media.php?artikel=<?= e(rawurlencode($post['slug'])) ?>#berita-terbaru">Baca Selengkapnya</a></article><?php endforeach; ?><?php if(!$posts): ?><p class="pesan-kosong">Belum ada berita.</p><?php endif; ?>
